                     </div>
                   </>
                 )}
               </div>

               {/* Thumbnails Gallery */}
               {hasMultipleImages && (
                 <div className="grid grid-cols-4 gap-3">
                   {images.map((img, idx) => (
                     <button
                       key={idx}
                       onClick={() => setCurrentImageIndex(idx)}
                       className={`relative rounded-lg overflow-hidden aspect-square border-2 transition-all duration-300 ${
                         idx === currentImageIndex 
