          // EXHIBIT DETAIL VIEW (Full Page)
          <ExhibitDetail 
            item={selectedExhibit}
            category={selectedCategory}
            onBack={handleBackToCategory}
            readingList={readingList}
            onToggleBook={toggleBook}
